import pandas as pd
import numpy as np

def clean(df):
    d = df.copy()
    # normalize text columns: strip whitespace
    for c in d.columns:
        if d[c].dtype == object:
            d[c] = d[c].apply(lambda v: v.strip() if isinstance(v, str) else v)
    # fix island label variant
    d['island'] = d['island'].replace({'Bisco': 'Biscoe'})
    # coerce numeric columns to numbers
    for c in ['bill_length_mm', 'bill_depth_mm', 'flipper_length_mm', 'body_mass_g', 'year']:
        if c in d.columns:
            d[c] = pd.to_numeric(d[c], errors='coerce')
    # drop exact duplicate rows
    d = d.drop_duplicates()
    # drop rows with missing group key (sex unknown -> do not guess)
    d = d[d['sex'].notna() & (d['sex'] != '')]
    return d.reset_index(drop=True)

def answer(df):
    d = clean(df)
    g = d.groupby('sex')['body_mass_g'].mean()
    return {str(k): round(float(v), 2) for k, v in g.items()}
